<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/commerce.php';$db=get_db();$db->beginTransaction();try{$quotes=$db->query('SELECT id FROM checkout_quotes WHERE status="open" AND expires_at<=UTC_TIMESTAMP() FOR UPDATE')->fetchAll();foreach($quotes as $quote){release_quote_reservations($quote['id']);$db->prepare('UPDATE checkout_quotes SET status="expired" WHERE id=:id')->execute(['id'=>$quote['id']]);}$bookings=$db->query('SELECT id,ticket_type_id,quantity FROM event_bookings WHERE status="payment_pending" AND reservation_expires_at<=UTC_TIMESTAMP() FOR UPDATE')->fetchAll();foreach($bookings as $booking){$db->prepare('UPDATE event_ticket_types SET reserved_quantity=GREATEST(0,reserved_quantity-:qty),updated_at=UTC_TIMESTAMP() WHERE id=:ticket')->execute(['qty'=>$booking['quantity'],'ticket'=>$booking['ticket_type_id']]);$db->prepare('UPDATE event_bookings SET status="expired",cancelled_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$booking['id']]);}$db->prepare('UPDATE sustainability_claims SET public_status="hidden",review_status="expired",updated_at=UTC_TIMESTAMP() WHERE valid_until<CURDATE() AND review_status="approved"')->execute();$db->prepare('UPDATE vendor_certificates SET verification_status="expired",updated_at=UTC_TIMESTAMP() WHERE valid_until IS NOT NULL AND valid_until<CURDATE() AND verification_status="verified"')->execute();$db->prepare('UPDATE auth_sessions SET revoked_at=UTC_TIMESTAMP(),revoke_reason="expired" WHERE revoked_at IS NULL AND expires_at<=UTC_TIMESTAMP()')->execute();$db->commit();echo 'Maintenance complete: '.count($quotes).' quotes and '.count($bookings).' bookings expired.'.PHP_EOL;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}
